const phasedRules=new Map();
async function loadPhaseRules(environment,phase){
 if(!environment||typeof environment!=='object')throw new Error('phase rules test environment missing');
 if(!phasedRules.has(phase)){
  const root=fileURLToPath(new URL('..',import.meta.url)),build=spawnSync(process.execPath,['tools/build_firestore_rules_deploy.mjs',`--phase=${phase}`],{cwd:root,encoding:'utf8'});
  if(build.error||(build.status??1)!==0)throw new Error(`phase rules build failed: ${phase}`);
  phasedRules.set(phase,readFileSync(new URL('../firebase/firestore.rules.deploy',import.meta.url),'utf8'));
 }
 const host=process.env.FIRESTORE_EMULATOR_HOST;
 if(typeof host!=='string'||!/^127\.0\.0\.1:[0-9]{2,5}$/.test(host))throw new Error('phase rules may only target loopback emulator');
 const response=await fetch(`http://${host}/emulator/v1/projects/danbridge-rules-test:securityRules`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({rules:{files:[{content:phasedRules.get(phase)}]}})});
 if(!response.ok)throw new Error(`phase rules load failed: ${phase}`);
 await new Promise(resolve=>setTimeout(resolve,1500));
}
