 const hard=createFirebaseRecordSyncV1V2HardPauseAdapter({environment:'staging',role:'owner',actor,serverTimestamp:()=>currentStamp,getDocumentFromServer:async path=>store.get(path)??null,runTransaction:transact}),hardPauseCompletion=await hard.execute(input);currentStamp=times[1];
