test('三階段U→V→Pair各6 authoritative reads/1 write，fresh replay與時間鏈完整',async()=>{
 const value=await fixture();let forgedIo=0;const authorityOnly=createFirebaseRecordSyncV1PostPauseScanAdapter({environment:'staging',role:'owner',actor,serverTimestamp:()=>times[1],getCollectionPageFromServer:async()=>{forgedIo++;return[]},getDocumentFromServer:async()=>{forgedIo++;return null},runTransaction:async()=>{forgedIo++}});await assert.rejects(()=>authorityOnly.executeU(value.hardPauseCompletion),/capability/);assert.equal(forgedIo,0);
 const u=await value.adapter.executeU(value.hardPauseCompletion),uHidden=value.adapter.consumeLocalUCompletion(u);assert.equal(u.writeCount,1);assert.equal(uHidden.uScanReceipt.startedAt,uHidden.hardPausePersistedAt);assert.throws(()=>{uHidden.uScanReceipt.startedAt='mutated'},TypeError);assert.deepEqual(value.transactions[1].map(row=>row[0]),[...Array(6).fill('get'),'set']);assert.throws(()=>consumeFirebaseRecordSyncV1PostPauseScanUCompletion(u),/capability/);
 const uReplay=await value.adapter.executeU(value.hardPauseCompletion);assert.equal(uReplay.writeCount,0);value.setStamp(2);const v=await value.adapter.executeV(u);assert.equal(v.writeCount,1);const vHidden=value.adapter.consumeLocalVCompletion(v);assert.equal(vHidden.vScanReceipt.startedAt,u.persistedAt);assert.ok(vHidden.vScanExecution);assert.deepEqual(value.transactions.at(-1).map(row=>row[0]),[...Array(6).fill('get'),'set']);assert.throws(()=>consumeFirebaseRecordSyncV1PostPauseScanVCompletion(v),/capability/);
 const vReplay=await value.adapter.executeV(u);assert.equal(vReplay.writeCount,0);value.setStamp(3);const pair=await value.adapter.executePair(v);assert.equal(pair.writeCount,1);const pairHidden=value.adapter.consumeLocalPairCompletion(pair);assert.equal(pairHidden.scanPair.matchedAt,v.persistedAt);assert.equal(pairHidden.scanPair.persistedAt,pair.persistedAt);const replay=await value.adapter.executePair(v);assert.equal(replay.writeCount,0);assert.throws(()=>consumeFirebaseRecordSyncV1PostPauseScanPairCompletion(pair),/capability/);
 const restartedU=await value.adapter.executeU(value.hardPauseCompletion),restartedV=await value.adapter.executeV(restartedU),restartedPair=await value.adapter.executePair(restartedV);assert.deepEqual([restartedU.writeCount,restartedV.writeCount,restartedPair.writeCount],[0,0,0]);
 assert.throws(()=>consumeFirebaseRecordSyncV1PostPauseScanUCompletion(structuredClone(u)),/capability/);assert.throws(()=>consumeFirebaseRecordSyncV1PostPauseScanVCompletion(structuredClone(v)),/capability/);assert.throws(()=>consumeFirebaseRecordSyncV1PostPauseScanPairCompletion(structuredClone(pair)),/capability/);
});

